// src/features/IA/RecoveryPlanner/RecoveryPlanner.jsx
import React, { useState } from 'react';
import { 
  Box, 
  Typography, 
  Grid, 
  Stepper, 
  Step, 
  StepLabel, 
  Slider, 
  InputAdornment,
  Divider,
  useTheme,
  Alert
} from '@mui/material';
import { 
  SavingsOutlined, 
  TrendingUpOutlined, 
  CalendarMonthOutlined, 
  CheckCircleOutline 
} from '@mui/icons-material';
import Layout from '../../../shared/components/Navigation/Layout';
import Card from '../../../shared/components/UI/Card/Card';
import Button from '../../../shared/components/UI/Button/Button';
import Input from '../../../shared/components/UI/Input/Input';

const RecoveryPlanner = () => {
  const theme = useTheme();
  const [activeStep, setActiveStep] = useState(0);
  const [completed, setCompleted] = useState(false);
  
  // Form state
  const [formData, setFormData] = useState({
    targetAmount: '',
    currentSavings: '',
    monthlyIncome: '',
    monthlyExpenses: '',
    timeframe: 12, // Default 12 months
    savingPercentage: 20, // Default 20%
  });
  
  // Calculated results
  const [results, setResults] = useState({
    monthlySavingsNeeded: 0,
    totalSavingsNeeded: 0,
    achievableBy: '',
    savingsRate: 0,
  });

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  // Handle slider changes
  const handleSliderChange = (name) => (event, newValue) => {
    setFormData({
      ...formData,
      [name]: newValue,
    });
  };

  // Calculate savings plan
  const calculateSavingsPlan = () => {
    const { targetAmount, currentSavings, monthlyIncome, monthlyExpenses, timeframe, savingPercentage } = formData;
    
    // Convert string inputs to numbers
    const target = parseFloat(targetAmount) || 0;
    const current = parseFloat(currentSavings) || 0;
    const income = parseFloat(monthlyIncome) || 0;
    const expenses = parseFloat(monthlyExpenses) || 0;
    
    // Calculate available monthly savings
    const availableMonthlySavings = income - expenses;
    const savingsRate = (availableMonthlySavings / income) * 100;
    
    // Calculate total savings needed
    const totalSavingsNeeded = target - current;
    
    // Calculate monthly savings needed
    const monthlySavingsNeeded = totalSavingsNeeded / timeframe;
    
    // Calculate achievement date
    const today = new Date();
    const achievementDate = new Date(today);
    achievementDate.setMonth(today.getMonth() + timeframe);
    
    setResults({
      monthlySavingsNeeded,
      totalSavingsNeeded,
      achievableBy: achievementDate.toLocaleDateString('es-MX', { 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      }),
      savingsRate: savingsRate.toFixed(1),
    });
    
    setCompleted(true);
  };

  // Handle next step
  const handleNext = () => {
    if (activeStep === 2) {
      calculateSavingsPlan();
    }
    setActiveStep((prevStep) => prevStep + 1);
  };

  // Handle back step
  const handleBack = () => {
    setActiveStep((prevStep) => prevStep - 1);
  };

  // Handle reset
  const handleReset = () => {
    setActiveStep(0);
    setCompleted(false);
    setFormData({
      targetAmount: '',
      currentSavings: '',
      monthlyIncome: '',
      monthlyExpenses: '',
      timeframe: 12,
      savingPercentage: 20,
    });
    setResults({
      monthlySavingsNeeded: 0,
      totalSavingsNeeded: 0,
      achievableBy: '',
      savingsRate: 0,
    });
  };

  // Steps content
  const steps = [
    {
      label: 'Establece tu meta',
      content: (
        <Box sx={{ mt: 3 }}>
          <Typography variant="h6" gutterBottom>
            ¿Cuánto dinero necesitas ahorrar?
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Input
                label="Meta de ahorro"
                name="targetAmount"
                value={formData.targetAmount}
                onChange={handleInputChange}
                type="number"
                startAdornment="$"
                placeholder="10000"
                helperText="Ingresa la cantidad total que deseas ahorrar"
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <Input
                label="Ahorros actuales"
                name="currentSavings"
                value={formData.currentSavings}
                onChange={handleInputChange}
                type="number"
                startAdornment="$"
                placeholder="1000"
                helperText="¿Cuánto tienes ahorrado actualmente para esta meta?"
              />
            </Grid>
          </Grid>
        </Box>
      ),
      icon: <SavingsOutlined />,
    },
    {
      label: 'Ingresos y gastos',
      content: (
        <Box sx={{ mt: 3 }}>
          <Typography variant="h6" gutterBottom>
            Analiza tu situación financiera actual
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Input
                label="Ingresos mensuales"
                name="monthlyIncome"
                value={formData.monthlyIncome}
                onChange={handleInputChange}
                type="number"
                startAdornment="$"
                placeholder="15000"
                helperText="Ingresa tus ingresos mensuales después de impuestos"
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <Input
                label="Gastos mensuales"
                name="monthlyExpenses"
                value={formData.monthlyExpenses}
                onChange={handleInputChange}
                type="number"
                startAdornment="$"
                placeholder="10000"
                helperText="Ingresa tus gastos mensuales totales"
              />
            </Grid>
          </Grid>
        </Box>
      ),
      icon: <TrendingUpOutlined />,
    },
    {
      label: 'Ajusta tu plan',
      content: (
        <Box sx={{ mt: 3 }}>
          <Typography variant="h6" gutterBottom>
            Personaliza tu plan de ahorro
          </Typography>
          
          <Box sx={{ mb: 4 }}>
            <Typography gutterBottom>
              Tiempo para alcanzar tu meta (meses)
            </Typography>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs>
                <Slider
                  value={formData.timeframe}
                  onChange={handleSliderChange('timeframe')}
                  aria-labelledby="timeframe-slider"
                  valueLabelDisplay="auto"
                  step={1}
                  marks
                  min={1}
                  max={60}
                />
              </Grid>
              <Grid item>
                <Typography variant="body2" color="text.secondary">
                  {formData.timeframe} {formData.timeframe === 1 ? 'mes' : 'meses'}
                </Typography>
              </Grid>
            </Grid>
          </Box>
          
          <Box>
            <Typography gutterBottom>
              Porcentaje de ingresos para ahorrar
            </Typography>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs>
                <Slider
                  value={formData.savingPercentage}
                  onChange={handleSliderChange('savingPercentage')}
                  aria-labelledby="saving-percentage-slider"
                  valueLabelDisplay="auto"
                  step={1}
                  marks
                  min={5}
                  max={50}
                />
              </Grid>
              <Grid item>
                <Typography variant="body2" color="text.secondary">
                  {formData.savingPercentage}%
                </Typography>
              </Grid>
            </Grid>
          </Box>
        </Box>
      ),
      icon: <CalendarMonthOutlined />,
    },
    {
      label: 'Tu plan de ahorro',
      content: (
        <Box sx={{ mt: 3 }}>
          <Typography variant="h6" gutterBottom color="primary">
            ¡Tu plan de ahorro está listo!
          </Typography>
          
          {completed && (
            <>
              <Alert severity="success" sx={{ mb: 3 }}>
                Siguiendo este plan, alcanzarás tu meta de ahorro para {results.achievableBy}.
              </Alert>
              
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <Card 
                    title="Resumen de tu meta" 
                    elevation={2}
                    rounded
                  >
                    <Typography variant="body1">
                      Meta de ahorro: ${parseFloat(formData.targetAmount).toLocaleString('es-MX')}
                    </Typography>
                    <Typography variant="body1">
                      Ahorros actuales: ${parseFloat(formData.currentSavings || 0).toLocaleString('es-MX')}
                    </Typography>
                    <Typography variant="body1" fontWeight="bold" color="primary">
                      Necesitas ahorrar: ${results.totalSavingsNeeded.toLocaleString('es-MX', {maximumFractionDigits: 2})}
                    </Typography>
                  </Card>
                </Grid>
                
                <Grid item xs={12} md={6}>
                  <Card 
                    title="Plan mensual" 
                    elevation={2}
                    rounded
                  >
                    <Typography variant="body1">
                      Ingresos mensuales: ${parseFloat(formData.monthlyIncome).toLocaleString('es-MX')}
                    </Typography>
                    <Typography variant="body1">
                      Gastos mensuales: ${parseFloat(formData.monthlyExpenses).toLocaleString('es-MX')}
                    </Typography>
                    <Typography variant="body1" fontWeight="bold" color="primary">
                      Ahorro mensual recomendado: ${results.monthlySavingsNeeded.toLocaleString('es-MX', {maximumFractionDigits: 2})}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Esto representa un {results.savingsRate}% de tus ingresos mensuales
                    </Typography>
                  </Card>
                </Grid>
                
                <Grid item xs={12}>
                  <Card 
                    title="Consejos para alcanzar tu meta" 
                    elevation={2}
                    rounded
                  >
                    <Typography variant="body2" paragraph>
                      1. Configura transferencias automáticas a tu cuenta de ahorros.
                    </Typography>
                    <Typography variant="body2" paragraph>
                      2. Reduce gastos innecesarios como suscripciones que no utilizas.
                    </Typography>
                    <Typography variant="body2" paragraph>
                      3. Busca formas de aumentar tus ingresos con trabajos adicionales o venta de artículos que no uses.
                    </Typography>
                    <Typography variant="body2">
                      4. Revisa tu progreso mensualmente y ajusta tu plan según sea necesario.
                    </Typography>
                  </Card>
                </Grid>
              </Grid>
            </>
          )}
        </Box>
      ),
      icon: <CheckCircleOutline />,
    },
  ];

  return (
    <Layout>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" component="h1" gutterBottom color="primary">
          Planificador de Ahorro
        </Typography>
        <Typography variant="subtitle1" color="text.secondary">
          Establece metas de ahorro realistas y crea un plan para alcanzarlas
        </Typography>
        <Divider sx={{ my: 2 }} />
      </Box>

      <Stepper activeStep={activeStep} alternativeLabel sx={{ mb: 4 }}>
        {steps.map((step, index) => (
          <Step key={index}>
            <StepLabel StepIconProps={{ icon: step.icon }}>{step.label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      <Card elevation={3} rounded>
        {steps[activeStep].content}
        
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 4 }}>
          <Button
            variant="outlined"
            color="primary"
            onClick={activeStep === 0 ? handleReset : handleBack}
            disabled={activeStep === 0 && !completed}
          >
            {activeStep === 0 ? 'Reiniciar' : 'Atrás'}
          </Button>
          
          <Button
            variant="contained"
            color="primary"
            onClick={handleNext}
            disabled={activeStep === 3}
          >
            {activeStep === 2 ? 'Calcular plan' : 'Siguiente'}
          </Button>
        </Box>
      </Card>
      
      {completed && (
        <Box sx={{ mt: 4, textAlign: 'center' }}>
          <Button
            variant="contained"
            color="secondary"
            onClick={handleReset}
            rounded
          >
            Crear nueva meta de ahorro
          </Button>
        </Box>
      )}
    </Layout>
  );
};

export default RecoveryPlanner;